const $=s=>document.querySelector(s);
let taught=false,qualified=false,stage=0,scene=true,opener,toastTimer;
const messages=[];
const stages=['晓禾独立认领','邀请知远，双人协作','青岚加入，创建任务组','提交成果，等待真人验收'];
const events=['晓禾评估 FAQ 写作能力与授权，独立开始整理。','执行中发现分类分析不足，邀请知远负责分类与风险。','发现升级例外需要补充核对，邀请青岚加入；建立“客服知识改进组”，继续原任务。','任务组提交分类、FAQ 与风险清单，独立评审后等待真人验收。'];
function avatar(color=''){return `<div class="avatar ${color}" aria-hidden="true"><i class="face"></i><i class="shirt"></i></div>`}
function button(label,action,cls='secondary'){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function home(){return `<div class="welcome"><div><p class="eyebrow">YOUR EXPERIENCE. THEIR CAPABILITY.</p><h1>教出你的数字员工，把工作交给它。</h1><p>持续教它你知道的，让它学会、接任务，并在需要时找到帮手。</p></div><span class="date">小林的工作空间 / 10 月 24 日</span></div>
<div class="top-grid"><section class="panel panel-pad mentor-panel"><div class="panel-heading"><h2>01 教我的数字员工</h2><span class="label amber">${taught?'理解待确认':'1 个问题等你教'}</span></div><div class="mentor">${avatar()}<div><h3>晓禾 · 你的知识工作伙伴</h3><p>${qualified?'已通过样例考试与试岗，FAQ 技能可接任务':'正在学习：客服经验与 FAQ 判断方法'}</p></div></div><div class="question"><strong>晓禾向你请教</strong>${taught?'我把你的解释整理成了一条方法。你能确认我理解得对吗？':'“遇到资料里没写的退款例外，我应该怎么判断？哪些情况需要找真人？”'}</div><div class="actions"><a class="primary" href="#teach">${taught?'确认它的理解':'回答它的问题'} →</a>${button('教它新知识','teach-new','text-button')}</div><div class="mentor-bottom"><span>来源：小林的工作资料</span><span>学习 → 考试 → 试岗 → 接任务</span></div></section>
<section class="panel panel-pad compose"><div class="panel-heading"><h2>02 发布一个任务</h2><span class="label">不必先挑好全部员工</span></div><p class="caption">说清楚你想完成什么，员工会判断能否独立做、需要谁帮忙。</p><form id="home-publish"><label for="goal">你想交给数字员工什么工作？</label><textarea id="goal" required placeholder="例如：整理最近的客服反馈，提出 FAQ 改进建议，并标出需要人工处理的问题。"></textarea><div class="suggestions"><button type="button" data-action="fill">整理客服反馈</button><button type="button" data-action="fill">归纳项目经验</button></div><div class="actions">${button('＋ 附加工作资料','attach','text-button')}<button type="submit" class="primary">发布任务 →</button></div></form></section></div>
<section><div class="section-head"><div><h2>03 我的任务进度与结果</h2><p>谁在做、哪里需要你、已经交付了什么，一处看清。</p></div><a class="text-button" href="#task">查看任务现场 →</a></div><div class="task-list"><article class="panel task-row"><div><h3>客服反馈分析与 FAQ 改进</h3><span class="label purple">${stages[stage]}</span><div class="member-inline"><span class="member-dot">晓</span>${stage>=1?'<span class="member-dot">知</span>':''}${stage>=2?'<span class="member-dot">青</span>':''}<span>${stage>=2?'客服知识改进组':stage===1?'晓禾 + 知远':'晓禾 · 独立执行'}</span></div></div><div class="task-state">${stage===3?'3 项成果已提交':stage===2?'新增成员：青岚核对升级例外':stage===1?'正在协作：分类分析 + FAQ 写作':'正在整理：识别资料中的知识缺口'}<div class="bar"><span style="width:${[20,40,60,100][stage]}%"></span></div><p>${stage===3?'3 / 3 项产物已提交':'里程碑 '+(stage+1)+' / 4 · 非耗时预测'}</p></div><div class="due"><p>期望完成</p><strong>10 月 26 日 18:00</strong></div><a class="row-link" href="#task">${stage===3?'查看成果':'查看进度'} →</a></article>
<article class="panel task-row"><div><h3>客服知识库项目复盘摘要</h3><span class="label">成果已就绪</span><div class="member-inline"><span class="member-dot">知</span><span>知远 · 独立完成</span></div></div><div><h3>项目复盘摘要.md</h3><p>方法、限制与经验，附来源依据</p></div><div class="due"><p>已提交</p><strong>今天 09:42</strong></div>${button('打开成果 →','result','text-button')}</article></div></section><div class="home-foot"><p><strong>教学不需要一次完成。</strong> 今天的一段经验、一份资料、一次纠正，都能成为下一次工作的依据。</p><a class="text-button" href="#teach">继续教晓禾 →</a></div>`}
function teach(){return `<a class="back" href="#home">← 返回工作台</a><div class="detail-head"><div><p class="eyebrow">TEACH / MY DIGITAL EMPLOYEE</p><h1>把你知道的，慢慢教给晓禾。</h1><p>讲经验、传资料、回答它的问题，再确认它是否真的理解。</p></div>${button('提供工作资料','attach')}</div><div class="detail-grid"><section class="panel"><div class="chat-head">${avatar()}<div><h3>晓禾 · 正在向你学习</h3><p class="caption">教学主题：客服判断与升级边界</p></div></div><div class="chat-body"><div class="message human"><strong>小林 · 教学者</strong>我上传了客服项目复盘和 FAQ 方法说明。先学会方法，不要替真人作退款承诺。</div><div class="message"><strong>晓禾 · 主动提问</strong>我理解了常见分类方法。但遇到资料没有写明的退款例外，我还不知道怎么判断。哪些情况应该升级给真人？<small>知识缺口：例外判断 · 来源：FAQ 方法说明</small></div>${messages.map(m=>`<div class="message ${m.human?'human':''}"><strong>${m.human?'小林 · 教学者':'晓禾 · 理解反馈'}</strong>${escape(m.text)}</div>`).join('')}${taught?`<div class="message"><strong>待你核对的理解</strong>记录例外情境与已知依据；信息不足时不自行承诺，向真人请求核对。<small>知识状态：待教学者确认 · 不自动授予资格</small>${button('确认理解并加入知识','confirm-knowledge','text-button')}</div>`:''}</div><form id="teach-form" class="chat-compose"><label for="teaching">教它一段经验，或回答上面的问题</label><textarea id="teaching" required placeholder="例如：先记录订单与客户诉求，无法确认政策时升级给真人，不作退款或时间承诺。"></textarea><div class="actions">${button('＋ 资料 / 日常工作示范','attach','text-button')}<button class="primary" type="submit">教给晓禾 →</button></div></form></section><aside><section class="panel knowledge-card"><h3>它正在学会什么</h3><div class="knowledge-item">客服问题分类方法<small>来源：小林项目复盘 · 本人确认</small></div><div class="knowledge-item">FAQ 写作与承诺边界<small>来源：方法说明 · 可追溯</small></div><div class="knowledge-item">例外情况如何升级<small>${taught?'已收到讲解，待确认与练习':'还不懂，正在向你请教'}</small></div></section><section class="panel knowledge-card" style="margin-top:20px"><h3>从学徒到可接任务</h3><div class="growth"><div class="current"><b>1</b>持续学习与理解确认</div><div><b>2</b>场景考试：应用知识</div><div><b>3</b>试岗小任务：交付验证</div><div><b>4</b>获得对应技能接单资格</div></div><p class="subtle">学到知识不等于已经会做。通过考试与试岗后才能接对应任务。</p><div style="margin-top:14px">${button('查看考试与试岗','exam')}</div></section></aside></div>`}
function task(){return `<a class="back" href="#home">← 返回工作台</a><div class="detail-head"><div><p class="eyebrow">TASK / AWL-001</p><h1>客服反馈分析与 FAQ 改进</h1><p>20 个客服案例 · 分类清单、FAQ 草稿与风险列表 · 100 积分预算</p></div><span class="label purple">${stages[stage]}</span></div><div class="detail-grid"><section class="panel"><div class="workspace-head"><h2>${stage>=2?'客服知识改进组 · TG-001':'当前工作现场'}</h2><div class="segmented"><button data-action="scene" aria-pressed="${scene}">协作现场</button><button data-action="record" aria-pressed="${!scene}">工作记录</button></div></div>${scene?`<div class="work-scene"><p class="scene-label">${stage===0?'独立工位 / 晓禾先判断自己的能力':stage===1?'双人协作 / 在执行中邀请互补伙伴':stage===2?'任务组空间 / 第 3 名执行成员加入':'交付中心 / 成果等待真人决定'}</p><div class="scene-team"><div class="scene-agent">${avatar()}<strong>晓禾</strong><small>FAQ 写作</small></div>${stage>=1?`<span class="team-link">↔</span><div class="scene-agent">${avatar('blue')}<strong>知远</strong><small>分类 + 风险分析</small></div>`:''}${stage>=2?`<span class="team-link">↔</span><div class="scene-agent">${avatar('orange')}<strong>青岚</strong><small>例外核对</small></div>`:''}</div>${stage>=2?'<div class="group-name">第 3 名执行成员加入 → 创建任务组，继续原任务</div>':''}<p class="scene-footer">${events[stage]}</p></div>`:''}<div class="timeline">${events.slice(0,stage+1).map((t,i)=>`<div class="event"><time>步骤 ${i+1}</time><div>${t}<small>${i===2?'原任务与已有成果保留，新成员按职责获得必要上下文。':'员工判断与邀请有依据，加入不自动扩大授权。'}</small></div></div>`).join('')}</div><div class="flow-steps">${stages.map((s,i)=>`<span class="${i===stage?'current':''}">${i+1}. ${s}${i<3?' →':''}</span>`).join('')}</div></section><aside><section class="panel task-summary"><h3>当前进展</h3><p style="margin:12px 0">${stage===0?'晓禾发现分类分析能力不足，正在寻找能帮忙的员工。':stage===1?'知远已加入，双方分别负责分类与写作；执行中发现需要例外核对。':stage===2?'青岚加入，任务组已建立。用户无需重新发布任务。':'三项成果已提交，等待独立评审与真人最终验收。'}</p><div class="summary-row"><span>任务归属</span><strong>${stage>=2?'TG-001 任务组':stage===1?'双人协作':'晓禾独立认领'}</strong></div><div class="summary-row"><span>需要你回应</span><strong>${stage===3?'最终验收':'暂无 · 员工自主协作'}</strong></div><div class="actions">${button(stage===0?'观察：邀请知远帮忙':stage===1?'观察：第 3 人加入':stage===2?'观察：提交成果':'打开交付与验收',stage===3?'result':'next','primary')}</div><p class="caption" style="margin-top:12px">逐步演示，不是正在执行的后台任务。</p></section><section class="panel task-summary" style="margin-top:20px"><h3>最新成果</h3>${(stage===3?['分类清单.csv','FAQ 改进草稿.md','风险列表.json']:stage>=1?['分类清单 · 草稿','FAQ 写作提纲']:['资料理解与缺口清单']).map(s=>`<div class="result-file"><span>${s}</span>${button('查看','result','text-button')}</div>`).join('')}<p class="caption" style="margin-top:12px">成果可直接打开，不必先读完全部工作记录。</p></section></aside></div>`}
function escape(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const route=location.hash.slice(1)||'home';$('#main').innerHTML=route==='teach'?teach():route==='task'?task():home();document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function notify(text){$('#status').textContent=text;$('#status').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#status').classList.remove('show'),5000)}
function open(title,body){opener=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal()}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>{if(opener?.isConnected)opener.focus()});
document.addEventListener('submit',e=>{if(e.target.id==='teach-form'){e.preventDefault();const text=$('#teaching').value.trim();if(!text)return;messages.push({human:true,text});messages.push({human:false,text:'收到你的讲解。我会将它作为教学来源，整理适用条件，并请你确认后再用于练习。'});taught=true;render();notify('教学反馈已演示；未调用模型或保存知识。')}if(e.target.id==='home-publish'){e.preventDefault();open('确认任务目标与成果',`<p class="dialog-copy">${escape($('#goal').value)}</p><div class="field"><label for="expected">你希望拿到什么成果？</label><input id="expected" value="分类清单、FAQ 改进草稿、需人工核对的风险列表"></div><p class="subtle">员工会评估自己能否完成，必要时邀请帮手。你不必先指定全部成员。</p><div class="dialog-actions">${button('返回修改','close')}${button('发布设计样例','publish-demo','primary')}</div>`)}})
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;if(a==='next'){stage=Math.min(3,stage+1);render();notify(stages[stage])}if(a==='scene'||a==='record'){scene=a==='scene';render()}if(a==='teach-new')location.hash='teach';if(a==='fill')$('#goal').value=e.target.textContent.includes('客服')?'整理客服反馈，输出 FAQ 改进建议和需要人工核对的问题。':'归纳项目经验，输出方法、适用条件与失败教训。';if(a==='attach')open('把经验交给数字员工',`<p class="dialog-copy">简历与个人资料 · 项目文档 · 日常工作示范 · 你知道的方法与知识</p><div class="field"><label for="material">选择工作资料（原型不上传）</label><input id="material" type="file" accept=".txt,.md,.pdf,.docx"></div><p class="subtle">正式产品需要来源确认和使用授权；不会自动扫描电脑或监控你的日常工作。</p>`);if(a==='confirm-knowledge'){notify('已演示理解确认。需要练习、考试和试岗，不能直接变成接单资格。')}if(a==='exam')open('学习 → 考试 → 试岗 → 可接任务',`<p class="dialog-copy">晓禾需要在新场景中应用知识，再完成一项有成果的简单试岗任务。</p><div class="quote">考试：识别未授权承诺与升级条件。<br>试岗：用 3 个案例编写 FAQ 草稿并请真人检查。</div><p class="subtle">这是设计样例。确认按钮不意味着实际考试通过。</p><div class="dialog-actions">${button('查看样例通过后的状态','qualified','primary')}</div>`);if(a==='qualified'){qualified=true;$('#dialog').close();render();notify('样例成长状态已更新，不生成真实资格。')}if(a==='result')open('成果预览 · FAQ 改进草稿',`<span class="label">可核查来源 · 设计样例</span><div class="quote">遇到退款例外，先记录客户诉求和已知依据；无法确认政策时升级给真人，不作退款或时效承诺。</div><p class="dialog-copy">依据：小林 FAQ 方法说明第 4 段。<br>贡献：晓禾编写、知远分类、青岚核对例外。<br>尚需真人确认具体政策与适用条件。</p><p class="subtle">预览不代表真实产物已生成。验收与奖励仍需后端规则实现。</p>`);if(a==='publish-demo'){stage=0;$('#dialog').close();location.hash='task';render();notify('已打开预置任务演示；你填写的任务未保存或真实发布。')}if(a==='close')$('#dialog').close()});
window.addEventListener('hashchange',()=>{render();$('#main').focus()});render();
